/** Generated by scaffold-crud-pages. Query hooks for LearningContent.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchLearningContentList,
  fetchLearningContentById,
  createLearningContent,
  updateLearningContent,
  deleteLearningContent,
  type FetchLearningContentListParams,
} from '~/services/httpServices/learningContentService';
import type { CreateLearningContentRequest, UpdateLearningContentRequest } from '~/types/learning-content';

const DOMAIN = 'learningContent';

export function useLearningContentList(params?: FetchLearningContentListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchLearningContentList(params),
  });
}

export function useLearningContent(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchLearningContentById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateLearningContent() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateLearningContentRequest) => createLearningContent(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateLearningContent() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateLearningContentRequest }) =>
      updateLearningContent(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteLearningContent() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteLearningContent(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
